#include <memory>

PyObject* callable = %1;

if (!PyCallable_Check(callable)) {
    PyErr_SetString(PyExc_TypeError, "Parameter must be a callable");
    return nullptr;
}

// Helper struct to safely manage PyObject lifetime when the connection/widget is destroyed
struct PythonCallableHolder {
    PyObject* cb;
    PythonCallableHolder(PyObject* p) : cb(p) {
        PyGILState_STATE gstate = PyGILState_Ensure();
        Py_INCREF(cb);
        PyGILState_Release(gstate);
    }
    ~PythonCallableHolder() {
        PyGILState_STATE gstate = PyGILState_Ensure();
        Py_DECREF(cb);
        PyGILState_Release(gstate);
    }
};

auto holder = std::make_shared<PythonCallableHolder>(callable);

// Connect C++ signal to a lambda that invokes the Python callable
QObject::connect(%CPPSELF, &QTermWidget::sendData, [holder](const char* data, int len) {
    PyGILState_STATE gstate = PyGILState_Ensure();

    PyObject* pyBytes = PyBytes_FromStringAndSize(data, len);
    if (pyBytes) {
        PyObject* result = PyObject_CallOneArg(holder->cb, pyBytes);
        if (!result) {
            PyErr_Print(); // Safely print traceback if Python slot raises an exception
        }
        Py_XDECREF(result);
        Py_DECREF(pyBytes);
    }

    PyGILState_Release(gstate);
});

Py_RETURN_NONE;
